svg.script:
/**/
(function() {
  const svg = document.getElementById('a16p8-svg');
  if (!svg) return;

  // Data State Store
  const state = {
    mode: 'materno', // materno | fetal | avidez | pcr | casos
    activeTarget: null
  };

  // Elements
  const tabs = {
    materno: document.getElementById('a16p8-tab-materno'),
    fetal: document.getElementById('a16p8-tab-fetal'),
    avidez: document.getElementById('a16p8-tab-avidez'),
    pcr: document.getElementById('a16p8-tab-pcr'),
    casos: document.getElementById('a16p8-tab-casos')
  };

  const groupEspiramicina = document.getElementById('a16p8-group-espiramicina');
  const groupTriplice = document.getElementById('a16p8-group-triplice');
  const stageTitle = document.getElementById('a16p8-stage-title');
  const stageSub = document.getElementById('a16p8-stage-sub');

  // Info Card Elements
  const infoTitle = document.getElementById('a16p8-info-title');
  const infoSubtitle = document.getElementById('a16p8-info-subtitle');
  const boxCondutaBg = document.getElementById('a16p8-box-conduta-bg');
  const txtCondutaTag = document.getElementById('a16p8-txt-conduta-tag');
  const txtCondutaMain = document.getElementById('a16p8-txt-conduta-main');
  const txtCondutaSub = document.getElementById('a16p8-txt-conduta-sub');
  const txtCondutaFoot = document.getElementById('a16p8-txt-conduta-foot');
  const txtMec1 = document.getElementById('a16p8-txt-mec-1');
  const txtMec2 = document.getElementById('a16p8-txt-mec-2');
  const txtWarnTitle = document.getElementById('a16p8-txt-warn-title');
  const txtWarnBody1 = document.getElementById('a16p8-txt-warn-body1');
  const txtWarnBody2 = document.getElementById('a16p8-txt-warn-body2');
  const txtWarnBody3 = document.getElementById('a16p8-txt-warn-body3');

  // Modes Configuration
  const modeConfigs = {
    materno: {
      title: "1. ALVO MATERNO: BARREIRA PLACENTÁRIA (ESPIRAMICINA)",
      sub: "Foco: Prevenir a transmissão da mãe para a placenta (<16 semanas)",
      infoTitle: "ALVO MATERNO (ESPIRAMICINA)",
      infoSub: "Esquema profilático de transmissão vertical no 1º trimestre",
      condutaTag: "CONDUTA IMEDIATA (<16 SEMANAS)",
      condutaColor: "var(--a16p8-teal)",
      condutaMain: "Espiramicina 1g V.O. de 8/8 horas",
      condutaSub: "Prescrever imediatamente ao identificar IgM+ / IgG+ recente ou soroconversão no 1ºT.",
      condutaFoot: "Acumula-se na placenta (4x conc.). Não atravessa barreira em nível terapêutico fetal.",
      mec1: "Concentra-se massivamente no tecido placentário, matando taquizoítos na placenta.",
      mec2: "Fraca travessia fetal: inofensiva ao feto, mas NÃO trata infecção fetal já estabelecida.",
      warnTitle: "ATENÇÃO: Não adiar o início da Espiramicina!",
      warn1: "1. Iniciar Espiramicina IMEDIATAMENTE enquanto aguarda confirmação laboratorial / avidez.",
      warn2: "2. Quanto mais precoce a infecção, MENOR a taxa de transmissão, mas MAIOR a gravidade fetal.",
      warn3: "3. NUNCA prescrever Sulfa+Pirimetamina antes de 16 semanas (Risco Teratogênico).",
      highlightEspiramicina: true,
      highlightTriplice: false
    },
    fetal: {
      title: "2. ALVO FETAL: TRÁTAMENTO DO FETO (SULFA + PIRIMETAMINA)",
      sub: "Foco: Tratar infecção fetal estabelecida (≥16 semanas / PCR +)",
      infoTitle: "ALVO FETAL (ESQUEMA TRÍPLICE)",
      infoSub: "Tratamento direto de taquizoítos nos tecidos fetais e SNC",
      condutaTag: "ESQUEMA FETAL (≥16 SEMANAS / PCR LA+)",
      condutaColor: "var(--a16p8-coral)",
      condutaMain: "Sulfadiazina + Pirimetamina + Ác. Folínico",
      condutaSub: "Sulfadiazina 1.5g 12/12h + Pirimetamina 25mg/dia + Ácido Folínico 15mg/dia V.O.",
      condutaFoot: "Atravessa eficientemente a placenta, alcançando SNC e olho fetal.",
      mec1: "Sulfadiazina + Pirimetamina bloqueiam sinergicamente a síntese de ácido fólico do parasita.",
      mec2: "Ácido Folínico (Leucovorina) é OBRIGATÓRIO para prevenir toxicidade medular materna/fetal.",
      warnTitle: "CONTRAINDICAÇÃO ABSOLUTA NO 1º TRIMESTRE!",
      warn1: "1. Pirimetamina é antagonista de folato: altamente TERATOGÊNICA no 1º Trimestre.",
      warn2: "2. Iniciar esquema fetal APENAS a partir de 16 semanas se PCR no LA for POSITIVO.",
      warn3: "3. Se PCR no LA for NEGATIVO: suspender esquema fetal e manter Espiramicina até o parto.",
      highlightEspiramicina: false,
      highlightTriplice: true
    },
    avidez: {
      title: "3. TESTE DE AVIDEZ DE IgG (&lt;16 SEMANAS)",
      sub: "Ferramenta decisiva para datar a infecção quando realizada no 1º Trimestre",
      infoTitle: "AVIDEZ DE IgG (JANELA &lt;16 SEMANAS)",
      infoSub: "Mede a força de ligação do anticorpo IgG ao antígeno do T. gondii",
      condutaTag: "INTERPRETAÇÃO DIAGNÓSTICA",
      condutaColor: "var(--a16p8-gold)",
      condutaMain: "Avidez Alta (&gt;60%) = Infecção Antiga (&gt;4 meses)",
      condutaSub: "Se realizada &lt;16 sem e Alta (&gt;60%): exclui infecção no 1ºT. Pode suspender Espiramicina!",
      condutaFoot: "Avidez Baixa (&lt;50%) ou Indeterminada: Mantém Espiramicina + Investigação Fetal (PCR).",
      mec1: "Anticorpos IgG recém-produzidos têm baixa avidez; amadurecem e ganham alta avidez após 4 meses.",
      mec2: "Se coletada com ≥16 semanas: Alta avidez NÃO exclui infecção no início da gestação!",
      warnTitle: "ARMADILHA CLÍNICA DE PROVA:",
      warn1: "1. Avidez de IgG &gt;60% SÓ tem valor para afastar infecção aguda se coletada com &lt; 16 semanas.",
      warn2: "2. Se a paciente chega no 2º/3º trimestre (ex: 20 sem) com IgM+: Avidez NÃO resolve mais.",
      warn3: "3. Nesses casos (&ge;16w), a conduta direta é realizar Amniocentese para PCR no LA.",
      highlightEspiramicina: true,
      highlightTriplice: false
    },
    pcr: {
      title: "4. AMNIOCENTESE &amp; PCR NO LÍQUIDO AMNIÓTICO (≥16 SEMANAS)",
      sub: "O divisor de águas definitivo para confirmar ou afastar infecção fetal",
      infoTitle: "DIAGNÓSTICO FETAL (PCR NO LA)",
      infoSub: "Padrão-ouro para confirmação de infecção fetal por Toxoplasma",
      condutaTag: "MOMENTO IDEAL: &ge;16 SEMANAS",
      condutaColor: "var(--a16p8-green)",
      condutaMain: "Amniocentese com PCR (Gene B1 / RE)",
      condutaSub: "Indicada se infecção materna confirmada/suspeita. Realizar &ge;16 sem e &ge;4 sem pós-infecção.",
      condutaFoot: "Sensibilidade &gt;90% e Especificidade próxima a 100%.",
      mec1: "Pesquisa DNA do T. gondii no líquido amniótico excretado pela urina fetal.",
      mec2: "PCR Positive (+): Confirma infecção fetal &rarr; Migrar para Esquema Tríplice Fetal.",
      warnTitle: "REGRAS DA AMNIOCENTESE:",
      warn1: "1. Não realizar antes de 16 semanas (risco de perdas gestacionais e falso-negativo).",
      warn2: "2. Respeitar intervalo mínimo de 4 a 8 semanas após a infecção aguda materna.",
      warn3: "3. Se PCR (-): Manter Espiramicina até o parto e acompanhar ultrassonografia fetal mensal.",
      highlightEspiramicina: true,
      highlightTriplice: true
    },
    casos: {
      title: "5. SIMULAÇÃO E CASOS CLÍNICOS DE PROVA",
      sub: "Aplicação prática dos conceitos de Avidez e Alvos Terapêuticos",
      infoTitle: "CASOS GUIA DE RESIDÊNCIA",
      infoSub: "Analise a conduta correta para cada perfil de paciente",
      condutaTag: "CASO 1 vs CASO 2",
      condutaColor: "var(--a16p8-red)",
      condutaMain: "Caso 1: IG 10sem, IgM+, IgG+, Avidez 75%",
      condutaSub: "Conduta: Infecção pré-concepcional (&gt;4m). Exclui infecção gestacional. Suspend Espiramicina!",
      condutaFoot: "Caso 2: IG 20sem, IgM+, IgG+, sem sorologia prévia &rarr; Indicar PCR no LA imediato!",
      mec1: "Caso 1 ilustra o poder da Alta Avidez no 1º Trimestre para tranquilizar a gestante.",
      mec2: "Caso 2 ilustra a gestante tardia: Avidez não serve mais &rarr; Vai direto para Amniocentese PCR.",
      warnTitle: "RESUMO ANCORA PARA A PROVA:",
      warn1: "• Alvo Materno = Espiramicina (Placenta, 1ºT, Previne transmissão).",
      warn2: "• Alvo Fetal = Sulfa + Pirimetamina + Ac. Folínico (Feto, &ge;16w / PCR+).",
      warn3: "• Divisor 16w = Limite da Avidez IgG e Início seguro da Amniocentese (PCR).",
      highlightEspiramicina: true,
      highlightTriplice: true
    }
  };

  function setMode(modeKey) {
    state.mode = modeKey;
    const config = modeConfigs[modeKey];
    if (!config) return;

    // Update Nav Tabs Active State
    Object.keys(tabs).forEach(k => {
      if (tabs[k]) {
        tabs[k].setAttribute('data-active', k === modeKey ? 'true' : 'false');
      }
    });

    // Update Stage Titles
    if (stageTitle) stageTitle.innerHTML = config.title;
    if (stageSub) stageSub.innerHTML = config.sub;

    // Update Visual Highlights
    if (groupEspiramicina) {
      groupEspiramicina.style.opacity = config.highlightEspiramicina ? '1' : '0.2';
    }
    if (groupTriplice) {
      groupTriplice.style.opacity = config.highlightTriplice ? '1' : '0.2';
    }

    // Update Info Box
    if (infoTitle) infoTitle.textContent = config.infoTitle;
    if (infoSubtitle) infoSubtitle.textContent = config.infoSub;
    if (boxCondutaBg) boxCondutaBg.style.stroke = config.condutaColor;
    if (txtCondutaTag) {
      txtCondutaTag.textContent = config.condutaTag;
      txtCondutaTag.style.fill = config.condutaColor;
    }
    if (txtCondutaMain) txtCondutaMain.textContent = config.condutaMain;
    if (txtCondutaSub) txtCondutaSub.textContent = config.condutaSub;
    if (txtCondutaFoot) txtCondutaFoot.textContent = config.condutaFoot;

    if (txtMec1) txtMec1.textContent = config.mec1;
    if (txtMec2) txtMec2.textContent = config.mec2;

    if (txtWarnTitle) txtWarnTitle.textContent = config.warnTitle;
    if (txtWarnBody1) txtWarnBody1.textContent = config.warn1;
    if (txtWarnBody2) txtWarnBody2.textContent = config.warn2;
    if (txtWarnBody3) txtWarnBody3.textContent = config.warn3;
  }

  // Attach Event Listeners to Tabs
  Object.keys(tabs).forEach(k => {
    if (tabs[k]) {
      tabs[k].addEventListener('click', function() {
        setMode(k);
      });
    }
  });

  // Hotspots Interactive Target
  const zoneMaternal = document.getElementById('a16p8-zone-maternal');
  const zonePlacenta = document.getElementById('a16p8-zone-placenta');
  const zoneFetus = document.getElementById('a16p8-zone-fetus');
  const marker16w = document.getElementById('a16p8-marker-16w');

  if (zoneMaternal) {
    zoneMaternal.addEventListener('click', () => setMode('materno'));
  }
  if (zonePlacenta) {
    zonePlacenta.addEventListener('click', () => setMode('materno'));
  }
  if (zoneFetus) {
    zoneFetus.addEventListener('click', () => setMode('fetal'));
  }
  if (marker16w) {
    marker16w.addEventListener('click', () => setMode('pcr'));
  }

  // Initialize default mode
  setMode('materno');
})();
/**/
